"""Agent tools. Arguments generated by the LLM are never trusted: each tool validates them with
Pydantic, and identity (phone, session) comes from the server-side AgentContext, never from the model."""

import json
import logging
from collections.abc import Awaitable, Callable
from dataclasses import dataclass, field
from datetime import date, datetime, timedelta
from typing import Any, Literal
from zoneinfo import ZoneInfo

from pydantic import BaseModel, Field, ValidationError, field_validator

from app.agent import n8n_client
from app.agent.n8n_client import ToolError
from app.db.repo import Repo
from app.llm.cost import Usage
from app.rag import retriever
from app.rag.retriever import Candidate

logger = logging.getLogger("smartcs.tools")

TZ = ZoneInfo("Asia/Ho_Chi_Minh")
STORES = {"TZ-HN01": "123 Cầu Giấy, Hà Nội", "TZ-HCM01": "456 Nguyễn Thị Minh Khai, Quận 3, TP.HCM"}
OPEN_HOUR, LAST_SLOT_HOUR = 8, 21
ORDER_ID = r"^TZ\d{5,}$"


def now() -> datetime:
    return datetime.now(TZ)


@dataclass
class AgentContext:
    session_id: str
    channel: str
    user_id: str
    turn_id: str
    phone: str | None = None
    repo: Repo | None = None
    dry_run: bool = False
    usage: Usage = field(default_factory=Usage)
    retrieved: dict[str, Candidate] = field(default_factory=dict)
    actions: list[str] = field(default_factory=list)
    tool_log: list[dict[str, Any]] = field(default_factory=list)

    def idempotency_key(self, tool: str) -> str:
        return f"{self.session_id}:{self.turn_id}:{tool}"


# ---------- argument schemas ----------


def _upper(v: Any) -> Any:
    return v.strip().upper() if isinstance(v, str) else v


class SearchKBArgs(BaseModel):
    query: str = Field(min_length=2, max_length=300, description="Search query in Vietnamese")


class LookupOrderArgs(BaseModel):
    order_id: str | None = Field(
        default=None, pattern=ORDER_ID, description="Order id like TZ10001; omit to list recent orders"
    )
    normalize_order_id = field_validator("order_id", mode="before")(_upper)


class CreateTicketArgs(BaseModel):
    category: Literal["warranty", "return", "delivery", "payment", "complaint", "other"]
    summary: str = Field(min_length=10, max_length=500, description="Clear summary of the customer's issue")
    order_id: str | None = Field(default=None, pattern=ORDER_ID)
    normalize_order_id = field_validator("order_id", mode="before")(_upper)


class BookAppointmentArgs(BaseModel):
    store_id: Literal["TZ-HN01", "TZ-HCM01"]
    start_time: datetime = Field(description="Local Vietnam time, ISO 8601, e.g. 2026-10-25T14:30")
    purpose: str = Field(min_length=3, max_length=200)

    @field_validator("start_time")
    @classmethod
    def _business_hours(cls, v: datetime) -> datetime:
        v = v.replace(tzinfo=TZ) if v.tzinfo is None else v.astimezone(TZ)
        current = now()
        if v < current + timedelta(hours=1):
            raise ValueError("must be at least 1 hour in the future")
        if v > current + timedelta(days=30):
            raise ValueError("must be within the next 30 days")
        if not (OPEN_HOUR <= v.hour <= LAST_SLOT_HOUR) or v.minute not in (0, 30) or v.second:
            raise ValueError("slots are 08:00-21:00 on the hour or half hour")
        if v.hour == LAST_SLOT_HOUR and v.minute:
            raise ValueError("last slot is 21:00")
        return v


class HandoffArgs(BaseModel):
    reason: Literal["customer_request", "no_information", "complaint", "other"]
    summary: str = Field(min_length=10, max_length=1000, description="Conversation summary for the agent")


# ---------- implementations ----------


async def search_kb(args: SearchKBArgs, ctx: AgentContext) -> dict:
    cands = await retriever.retrieve(args.query, usage=ctx.usage)
    for c in cands:
        ctx.retrieved[c.hit.chunk_id] = c
    if not cands:
        return {"documents": [], "note": "No relevant documents found."}
    return {
        "documents": [
            {"id": c.hit.chunk_id, "title": c.hit.title, "section": c.hit.section, "text": c.hit.text}
            for c in cands
        ]
    }


def _need_phone(ctx: AgentContext) -> dict:
    ctx.actions.append("request_phone")
    if ctx.channel == "web":
        msg = "Order data is only available on Telegram after phone verification."
    else:
        msg = "Ask the customer to tap the 'Chia sẻ số điện thoại' button to verify their phone first."
    return {"error": "phone_not_verified", "message": msg}


def _add_months(d: date, months: int) -> date:
    y, m = divmod(d.month - 1 + months, 12)
    y, m = d.year + y, m + 1
    for day in (d.day, 30, 29, 28):
        try:
            return date(y, m, day)
        except ValueError:
            continue
    raise ValueError("invalid date")  # pragma: no cover


def _format_order(o: dict) -> dict:
    items = o["items"] if isinstance(o["items"], list) else json.loads(o["items"])
    delivered = o["delivered_at"].astimezone(TZ).date() if o["delivered_at"] else None
    for it in items:
        until = _add_months(delivered, it["warranty_months"]) if delivered else None
        it["warranty_until"] = until.isoformat() if until else None
    return {
        "order_id": o["order_id"],
        "status": o["status"],
        "total_vnd": o["total_vnd"],
        "ordered_on": o["created_at"].astimezone(TZ).date().isoformat(),
        "delivered_on": delivered.isoformat() if delivered else None,
        "items": items,
    }


async def lookup_order(args: LookupOrderArgs, ctx: AgentContext) -> dict:
    if not ctx.phone:
        return _need_phone(ctx)
    if ctx.repo is None:
        raise ToolError("order database unavailable")
    orders = await ctx.repo.get_orders(ctx.phone, args.order_id)
    if not orders:
        # Same answer whether the order does not exist or belongs to someone else.
        return {"orders": [], "note": "No matching order for this verified customer."}
    return {"orders": [_format_order(o) for o in orders]}


async def create_ticket(args: CreateTicketArgs, ctx: AgentContext) -> dict:
    if args.order_id:
        if not ctx.phone:
            return _need_phone(ctx)
        if ctx.repo is not None and not await ctx.repo.get_orders(ctx.phone, args.order_id):
            return {"error": "order_not_found", "message": "Order not found for this customer."}
    payload = {
        "idempotency_key": ctx.idempotency_key("create_ticket"),
        "session_id": ctx.session_id,
        "customer_phone": ctx.phone or "",
        "order_id": args.order_id or "",
        "category": args.category,
        "summary": args.summary,
    }
    res = {"ticket_id": "TK-DRYRUN", "status": "open"} if ctx.dry_run else await n8n_client.call_tool(
        "create-ticket", payload
    )
    ctx.actions.append("ticket_created")
    return {"ticket_id": res["ticket_id"], "status": res.get("status", "open")}


async def book_appointment(args: BookAppointmentArgs, ctx: AgentContext) -> dict:
    payload = {
        "idempotency_key": ctx.idempotency_key("book_appointment"),
        "session_id": ctx.session_id,
        "customer_phone": ctx.phone or "",
        "store_id": args.store_id,
        "start_time": args.start_time.isoformat(),
        "purpose": args.purpose,
    }
    res = {"event_id": "AP-DRYRUN", "result": "booked"} if ctx.dry_run else await n8n_client.call_tool(
        "book-appointment", payload
    )
    if res.get("result") == "slot_taken":
        return {"error": "slot_taken", "message": "That slot is already booked. Suggest another time."}
    ctx.actions.append("appointment_booked")
    return {
        "event_id": res["event_id"],
        "store": f"{args.store_id} ({STORES[args.store_id]})",
        "start_time": args.start_time.strftime("%H:%M %d/%m/%Y"),
    }


async def handoff_to_human(args: HandoffArgs, ctx: AgentContext) -> dict:
    payload = {
        "idempotency_key": ctx.idempotency_key("handoff_to_human"),
        "session_id": ctx.session_id,
        "channel": ctx.channel,
        "customer_phone": ctx.phone or "",
        "reason": args.reason,
        "summary": args.summary,
    }
    if not ctx.dry_run:
        await n8n_client.call_tool("handoff", payload)
    ctx.actions.append("handoff")
    return {"queued": True}


# ---------- registry ----------


@dataclass(frozen=True)
class Tool:
    name: str
    description: str
    args: type[BaseModel]
    fn: Callable[[Any, AgentContext], Awaitable[dict]]

    def spec(self) -> dict:
        schema = self.args.model_json_schema()
        schema.pop("title", None)
        return {"type": "function", "function": {"name": self.name, "description": self.description,
                                                 "parameters": schema}}


TOOLS: dict[str, Tool] = {
    t.name: t
    for t in (
        Tool("search_kb", "Search TechZone policy documents (warranty, returns, shipping, payment, "
             "membership, troubleshooting FAQ).", SearchKBArgs, search_kb),
        Tool("lookup_order", "Look up the verified customer's orders: status, dates, items and "
             "warranty end date per item.", LookupOrderArgs, lookup_order),
        Tool("create_ticket", "Create a support ticket for staff follow-up (warranty claim, return, "
             "delivery problem, complaint).", CreateTicketArgs, create_ticket),
        Tool("book_appointment", "Book a store visit (store_id TZ-HN01 = Hanoi, TZ-HCM01 = HCMC). "
             "The tool validates the slot.", BookAppointmentArgs, book_appointment),
        Tool("handoff_to_human", "Escalate the conversation to a human support agent.",
             HandoffArgs, handoff_to_human),
    )
}
TOOL_SPECS = [t.spec() for t in TOOLS.values()]


async def dispatch(name: str, raw_args: str, ctx: AgentContext) -> dict:
    tool = TOOLS.get(name)
    if tool is None:
        return {"error": "unknown_tool", "message": f"No tool named {name}."}
    try:
        args = tool.args.model_validate_json(raw_args or "{}")
    except ValidationError as err:
        details = [
            {"field": ".".join(map(str, e["loc"])), "problem": e["msg"]}
            for e in err.errors(include_url=False, include_context=False, include_input=False)
        ]
        ctx.tool_log.append({"tool": name, "ok": False, "error": "invalid_arguments"})
        return {"error": "invalid_arguments", "details": details[:5]}
    try:
        result = await tool.fn(args, ctx)
    except ToolError as err:
        logger.warning("tool %s failed: %s", name, err)
        result = {"error": "tool_error", "message": "The system could not complete this action right now."}
    ctx.tool_log.append({"tool": name, "args": args.model_dump(mode="json"), "ok": "error" not in result})
    return result
